import type { Meta, StoryObj } from "@storybook/vue3";
import { h, markRaw } from "vue";
import { kozmosIconDefinitions, Settings01 } from "@kozmos-ds/icons/vue";
import { KozmosIcon } from "../../index";

/**
 * Vue's Icon: the stories React's has, with the same names and args,
 * each inside the KozmosThemeProvider the Storybook's decorator gives every
 * story. test/parity draws each of React's in both and holds Vue's render to
 * React's. Generated by `port Icon`; Sizes, Colors and Registry drawn by hand.
 */
type Args = Record<string, unknown>;
const SLOTS = [];

const meta: Meta<Args> = {
  title: "Vue/Foundations/Icons/Icon",
  component: KozmosIcon,
  // React's node props are Vue's slots: `children` the default slot, the
  // rest slots of their own names, each drawing its arg's text.
  render: (args) => ({
    setup: () => () => {
      const props: Args = {};
      const slots: Record<string, () => string> = {};
      for (const [key, value] of Object.entries(args)) {
        if (!SLOTS.includes(key)) props[key] = value;
        else if (value !== undefined && value !== null)
          slots[key === "children" ? "default" : key] = () => String(value);
      }
      return h(KozmosIcon, props, slots);
    },
  }),
};

export default meta;
type Story = StoryObj<Args>;

export const Default: Story = {
  args: {
    name: "home-line",
  },
};

/** React's Sizes: one glyph at each of the five sizes. */
export const Sizes: Story = {
  render: () => ({
    components: { KozmosIcon },
    template: `
      <div class="flex items-end gap-4">
        <KozmosIcon name="user-01" size="xs" />
        <KozmosIcon name="user-01" size="sm" />
        <KozmosIcon name="user-01" size="md" />
        <KozmosIcon name="user-01" size="lg" />
        <KozmosIcon name="user-01" size="xl" />
      </div>
    `,
  }),
};

/** React's Colors: a glyph handed as its component, in each colour. */
export const Colors: Story = {
  render: () => ({
    components: { KozmosIcon },
    setup: () => ({ Settings: markRaw(Settings01) }),
    template: `
      <div class="flex items-center gap-4">
        <KozmosIcon :icon="Settings" color="default" />
        <KozmosIcon :icon="Settings" color="muted" />
        <KozmosIcon :icon="Settings" color="primary" />
        <KozmosIcon :icon="Settings" color="destructive" />
      </div>
    `,
  }),
};

/** React's Registry: every icon in the library, by its name. */
export const Registry: Story = {
  render: () => ({
    components: { KozmosIcon },
    setup: () => ({
      names: kozmosIconDefinitions.map((definition) => definition.name),
    }),
    template: `
      <div class="grid grid-cols-2 gap-3 sm:grid-cols-4 md:grid-cols-6">
        <div
          v-for="name in names"
          :key="name"
          class="flex items-center gap-2 rounded border p-2 text-xs"
        >
          <KozmosIcon :name="name" size="sm" />
          <span class="truncate">{{ name }}</span>
        </div>
      </div>
    `,
  }),
};
